import crypto from 'node:crypto'
import { compactSyntheticLineage } from './lineage-compact.js'
import { canonicalEvidencePayload, sha256 as evidenceSha256 } from './evidence-v3.js'
import { repairEvidenceStepsV3 } from './evidence-repair.js'
import { cleanStepRequest } from './step-request.js'

/**
 * v2 -> v3 migration.
 *
 * v2 had to satisfy "finding must live under a verify intent", so the state
 * layer synthesized an autoGenerated verify intent for every finding. That is
 * a graph workaround, not a domain model: it doubles the graph and every
 * projection/UI/report needs to special-case those wrappers.
 *
 * v3 makes findings first-class:
 *   direction (planning) -> finding (result)
 *    ^                          |
 *    └── evidenceIds / validationIds / steps
 *
 * This module is intentionally pure: it takes a v2 state, returns a new v3
 * state and stats. It does not write storage. Dry-run tooling can call it on
 * every historical session before the runtime switch.
 */

export const V3_VERSION = 3

const DIRECTION_KINDS = new Set(['recon', 'verify', 'exploit', 'info', 'report'])
const SEVERITIES = new Set(['critical', 'high', 'medium', 'low', 'info'])

function text(value) {
  return typeof value === 'string' ? value : value == null ? '' : String(value)
}

function clone(value) {
  return structuredClone(value)
}

function sha256(value) {
  return crypto.createHash('sha256').update(text(value)).digest('hex')
}

function normalizeTitle(value) {
  return text(value).replace(/\s+/g, ' ').trim()
}

function isAutoIntent(intent) {
  if (!intent || typeof intent !== 'object') return false
  // Only an explicit marker counts. The old title heuristic
  // (/^(验证|verify)[:：]/ && kind === 'verify') deleted real verification
  // directions on every v3 write, because the v3->v2 compatibility layer
  // does not carry autoGenerated back (see state-v3-bridge.js).
  return intent.autoGenerated === true || intent.legacyAuto === true
}

function inferDirectionKind(intent) {
  const kind = text(intent?.kind)
  if (DIRECTION_KINDS.has(kind)) return kind
  const title = normalizeTitle(intent?.title).toLowerCase()
  if (/(验证|复现|利用|exploit|rce|注入|越权|上传|读取)/i.test(title)) return 'verify'
  return 'recon'
}

function normalizeSeverity(value) {
  const severity = text(value || 'medium')
  return SEVERITIES.has(severity) ? severity : 'medium'
}

function factDirectionId(fact, indexes) {
  const { intentById } = indexes
  const intentId = text(fact?.intentId || fact?.directionId)
  if (!intentId) return null
  const intent = intentById.get(intentId)
  if (!intent) return intentId
  if (isAutoIntent(intent)) {
    const resolved = resolveAutoChain(intent, indexes)
    return resolved.directionId || resolved.topAutoId || null
  }
  return intent.id
}

/**
 * Follow the v2 auto-verify parent chain.
 * Returns the nearest non-auto direction if one exists; otherwise returns the
 * top-most auto intent which the migration must keep as a real verify
 * direction (legacy orphan wrapper). This avoids silently dropping provenance.
 */
function resolveAutoChain(intent, indexes, seen = new Set()) {
  const { edges, intentById, factById, goalId } = indexes
  if (!intent) return { directionId: null, topAutoId: null }
  if (!isAutoIntent(intent)) return { directionId: intent.id, topAutoId: null }
  if (seen.has(intent.id)) return { directionId: null, topAutoId: intent.id }
  seen.add(intent.id)
  const parent = findDerivedParent(intent.id, edges)
  if (parent) {
    const parentIntent = intentById.get(parent.sourceId)
    if (parentIntent) return resolveAutoChain(parentIntent, indexes, seen)
    const parentFact = factById.get(parent.sourceId)
    if (parentFact) {
      const direction = factDirectionId(parentFact, indexes)
      return direction
        ? { directionId: direction, topAutoId: null }
        : { directionId: null, topAutoId: intent.id }
    }
    if (String(parent.sourceId) === String(goalId)) return { directionId: null, topAutoId: intent.id }
  }
  if (intent.sourceIntentId && intentById.has(intent.sourceIntentId)) {
    return resolveAutoChain(intentById.get(intent.sourceIntentId), indexes, seen)
  }
  if (intent.sourceFactId && factById.has(intent.sourceFactId)) {
    const direction = factDirectionId(factById.get(intent.sourceFactId), indexes)
    return direction
      ? { directionId: direction, topAutoId: null }
      : { directionId: null, topAutoId: intent.id }
  }
  return { directionId: null, topAutoId: intent.id }
}

function buildIndexes(state) {
  const intents = Array.isArray(state?.intents) ? state.intents : []
  const facts = Array.isArray(state?.facts) ? state.facts : []
  const edges = Array.isArray(state?.edges) ? state.edges : []
  const intentById = new Map(intents.map((intent) => [intent.id, intent]))
  const factById = new Map(facts.map((fact) => [fact.id, fact]))
  return { intents, facts, edges, intentById, factById, goalId: text(state?.goal?.id) }
}

function findFactEdgeToFinding(finding, edges, factById) {
  return edges.find((edge) => edge && edge.kind === 'derived_from' && edge.targetId === finding.id && factById.has(edge.sourceId))
}

function findDerivedParent(edgeTargetId, edges) {
  return edges.find((edge) => edge && edge.kind === 'derived_from' && edge.targetId === edgeTargetId)
}

function resolveFindingDirection(finding, indexes) {
  const { edges, intentById, factById } = indexes
  const factEdge = findFactEdgeToFinding(finding, edges, factById)
  if (factEdge) {
    const fact = factById.get(factEdge.sourceId)
    const factIntentId = factDirectionId(fact, indexes)
    if (factIntentId) return factIntentId
  }
  const current = intentById.get(text(finding?.intentId))
  if (!current) return null
  if (!isAutoIntent(current)) return current.id
  const resolved = resolveAutoChain(current, indexes)
  return resolved.directionId || resolved.topAutoId || null
}

function stepsForFinding(finding) {
  const rawSteps = Array.isArray(finding?.reproducibleSteps) && finding.reproducibleSteps.length > 0
    ? finding.reproducibleSteps
    : (Array.isArray(finding?.steps) ? finding.steps : [])
  const notes = Array.isArray(finding?.stepNotes) ? finding.stepNotes : []
  const responses = Array.isArray(finding?.stepResponses) ? finding.stepResponses : []
  const expectedValues = Array.isArray(finding?.stepExpected) ? finding.stepExpected : []
  return rawSteps.map((raw, index) => {
    const structured = raw && typeof raw === 'object' ? raw : null
    const note = text(notes[index] ?? structured?.note)
    // Agents often prepend the human explanation to the raw packet inside
    // reproducibleSteps. Keep the explanation in step.note; the evidence
    // request must start at the replayable HTTP request line.
    const request = cleanStepRequest(note, structured?.request ?? raw)
    return {
      note,
      request,
      response: text(responses[index] ?? structured?.response),
      expected: text(expectedValues[index] ?? structured?.expected)
    }
  })
}

function findingRootCauseKey(finding) {
  const key = normalizeTitle(finding?.dedupeKey || '')
  if (key !== '') return key
  return `title:${normalizeTitle(finding?.title).toLowerCase()}`
}

/**
 * @param {object} input v2 state
 * @param {{now?: number}} [options]
 * @returns {{state: object, stats: object}}
 */
export function migrateToV3(input, options = {}) {
  if (!input || typeof input !== 'object') throw new Error('migrateToV3: state required')
  const now = Number.isFinite(options.now) ? options.now : Date.now()
  if (Number(input.version) >= V3_VERSION) {
    const compacted = compactSyntheticLineage(clone(input))
    const repaired = repairEvidenceStepsV3(compacted.state)
    const state = repaired.changed ? repaired.state : compacted.state
    return {
      state,
      stats: {
        changed: compacted.changed || repaired.changed,
        fromVersion: Number(input.version) || 3,
        toVersion: V3_VERSION,
        removedAutoIntents: compacted.removed.length,
        evidenceCreated: Array.isArray(state.evidence) ? state.evidence.length : 0,
        validationsCreated: Array.isArray(state.validations) ? state.validations.length : 0,
        findingsWithoutDirection: (state.findings || []).filter((finding) => !finding.directionId).length
      }
    }
  }

  const source = clone(input)
  const indexes = buildIndexes(source)
  const { intents, facts, edges, intentById, factById } = indexes
  // Never remove a direction that a queue task still points at: dropping it
  // would orphan live work and rewrite task ownership to a done direction.
  const protectedIds = new Set()
  for (const task of (Array.isArray(source.queue) ? source.queue : [])) {
    const id = text(task?.directionId || task?.intentId)
    if (id) protectedIds.add(id)
  }
  const droppedAuto = (intent) => isAutoIntent(intent) && !protectedIds.has(intent.id)
  const autoIntents = intents.filter(droppedAuto)
  // Synthetic verify wrappers are v2 write-contract scaffolding, never domain
  // directions. All of them are removed; findings attach to the nearest real
  // direction or to the goal when no real source exists.
  const removedAutoIds = new Set(autoIntents.map((intent) => intent.id))
  const directions = []
  for (const intent of intents) {
    if (droppedAuto(intent)) continue
    const kind = inferDirectionKind(intent)
    directions.push({
      id: intent.id,
      title: normalizeTitle(intent.title),
      detail: text(intent.detail),
      doneWhen: text(intent.doneWhen),
      kind,
      state: text(intent.state || (isAutoIntent(intent) ? 'done' : 'open')),
      stateReason: text(intent.stateReason),
      priority: Number.isFinite(intent.priority) ? intent.priority : 5,
      dependsOn: Array.isArray(intent.dependsOn) ? intent.dependsOn.slice() : [],
      ...(intent.sourceFactId ? { sourceFactId: intent.sourceFactId } : {}),
      ...(isAutoIntent(intent) ? { legacyAuto: true } : {}),
      createdAt: Number(intent.createdAt) || now,
      updatedAt: Number(intent.updatedAt) || Number(intent.createdAt) || now
    })
  }
  const directionIds = new Set(directions.map((direction) => direction.id))
  const normalizedFacts = facts.map((fact) => {
    const directionId = factDirectionId(fact, indexes)
    return {
      ...fact,
      directionId: directionId && directionIds.has(directionId) ? directionId : (text(source.goal?.id) || null)
    }
  })
  const factIds = new Set(normalizedFacts.map((fact) => fact.id))

  const findings = []
  const evidence = []
  const validations = []
  for (const oldFinding of Array.isArray(source.findings) ? source.findings : []) {
    const finding = clone(oldFinding)
    const directionId = resolveFindingDirection(finding, indexes)
    finding.directionId = directionId && directionIds.has(directionId) ? directionId : (text(source.goal?.id) || null)
    finding.sourceStatus = directionId && directionIds.has(directionId) ? 'linked' : 'unbound'
    finding.rootCauseKey = findingRootCauseKey(finding)
    finding.severity = normalizeSeverity(finding.severity)
    finding.steps = stepsForFinding(finding)
    delete finding.steps_raw
    delete finding.intentId
    const evidenceIds = []
    for (let index = 0; index < finding.steps.length; index += 1) {
      const step = finding.steps[index]
      const raw = text(step.request)
      if (raw.trim() === '') continue
      const evidenceId = `evidence-${finding.id}-${index + 1}`
      const record = {
        id: evidenceId,
        findingId: finding.id,
        kind: 'http-step',
        index: index + 1,
        request: raw,
        response: text(step.response),
        expected: text(step.expected),
        note: text(step.note),
        sha256: '',
        createdAt: Number(finding.createdAt) || now
      }
      record.sha256 = evidenceSha256(canonicalEvidencePayload(record))
      evidence.push(record)
      evidenceIds.push(evidenceId)
    }
    finding.evidenceIds = evidenceIds
    if (oldFinding?.validation && typeof oldFinding.validation === 'object') {
      const validationId = `validation-${finding.id}`
      validations.push({
        id: validationId,
        findingId: finding.id,
        verdict: text(oldFinding.validation.verdict),
        validator: text(oldFinding.validation.validator),
        notes: text(oldFinding.validation.notes),
        evidenceIds: evidenceIds.slice(),
        evidenceRefs: Array.isArray(oldFinding.validation.evidenceRefs)
          ? oldFinding.validation.evidenceRefs.filter((item) => typeof item === 'string' && item !== '')
          : [],
        at: Number(oldFinding.validation.at) || Number(finding.updatedAt) || now
      })
      finding.validationId = validationId
      delete finding.validation
    }
    findings.push(finding)
  }
  const findingIds = new Set(findings.map((finding) => finding.id))
  const assetIds = new Set((Array.isArray(source.assets) ? source.assets : []).map((asset) => asset.id))
  const digestIds = new Set((Array.isArray(source.digests) ? source.digests : []).map((digest) => digest.id))
  const goalId = text(source.goal?.id)
  const keptNodeIds = new Set([goalId, ...directionIds, ...factIds, ...assetIds, ...digestIds])
  const nextEdges = edges.filter((edge) => {
    if (!edge || edge.kind === 'proves') return false
    if (!keptNodeIds.has(edge.sourceId) || !keptNodeIds.has(edge.targetId)) return false
    // Removed synthetic verify wrappers and finding edges are represented by
    // finding.directionId + evidence/validation in v3.
    if (removedAutoIds.has(edge.sourceId) || removedAutoIds.has(edge.targetId)) return false
    return true
  }).map((edge) => ({ ...edge }))

  const queue = (Array.isArray(source.queue) ? source.queue : []).map((task) => {
    const directionId = resolveFindingDirection({ ...task, intentId: task.intentId }, indexes)
    const valid = directionId && directionIds.has(directionId)
    return {
      ...task,
      directionId: valid ? directionId : null,
      ...(valid ? {} : {
        state: ['pending', 'claimed', 'running'].includes(task.state) ? 'dead' : task.state,
        error: task.error || 'lineage migrated: synthetic direction removed'
      })
    }
  })

  const counters = { ...(source.counters || {}) }
  counters.intent = Math.max(Number(counters.intent) || 0, directions.length)
  counters.finding = Math.max(Number(counters.finding) || 0, findings.length)
  counters.evidence = evidence.length
  counters.validation = validations.length
  counters.task = Math.max(Number(counters.task) || 0, queue.length)

  const state = {
    ...source,
    version: V3_VERSION,
    goal: source.goal ? { ...source.goal } : source.goal,
    directions,
    findings,
    facts: normalizedFacts,
    evidence,
    validations,
    assets: Array.isArray(source.assets) ? source.assets.map((asset) => ({ ...asset })) : [],
    digests: Array.isArray(source.digests) ? source.digests.map((digest) => ({ ...digest })) : [],
    coverage: Array.isArray(source.coverage) ? source.coverage.map((item) => ({ ...item })) : [],
    queue,
    edges: nextEdges,
    counters,
    migration: {
      fromVersion: Number(source.version) || 2,
      toVersion: V3_VERSION,
      at: now,
      removedAutoIntents: autoIntents.length,
      keptAutoDirections: 0,
      evidenceCreated: evidence.length,
      validationsCreated: validations.length
    }
  }
  delete state.intents
  return {
    state,
    stats: {
      changed: true,
      fromVersion: Number(source.version) || 2,
      toVersion: V3_VERSION,
      directions: directions.length,
      findings: findings.length,
      removedAutoIntents: autoIntents.length,
      keptAutoDirections: 0,
      evidenceCreated: evidence.length,
      validationsCreated: validations.length,
      findingsWithoutDirection: findings.filter((finding) => !finding.directionId).length
    }
  }
}

export function migrateAllToV3(states, options = {}) {
  const results = []
  for (const [sessionId, row] of Object.entries(states || {})) {
    const input = row && row.state ? row.state : row
    const migrated = migrateToV3(input, options)
    results.push({ sessionId, ...migrated.stats, state: migrated.state })
  }
  return results
}
